'use strict';
const KEY='pulse.morrow.projects.v1';
const seed=[
{id:'forma',name:'Brand world',client:'Forma',code:'FMA-001',team:'Brand design',owner:'Miki Chen',initials:'MC',avatar:'',status:'In progress',progress:68,due:'2026-11-12',art:'forma',description:'A considered identity for a new generation of everyday objects. Building the language, materials and small details that make Forma feel unmistakably itself.',tasks:[{name:'Strategy & creative direction',done:true},{name:'Core visual identity',done:true},{name:'Brand applications',done:false},{name:'Guidelines & handoff',done:false}]},
{id:'onda',name:'Digital flagship',client:'Onda',code:'OND-002',team:'Digital design',owner:'Leo Park',initials:'LP',avatar:'two',status:'In review',progress:86,due:'2026-11-08',art:'onda',description:'A digital home for a new kind of sound. An expressive, accessible storefront that makes discovery feel as good as listening.',tasks:[{name:'Information architecture',done:true},{name:'Visual design',done:true},{name:'Interactive prototype',done:true},{name:'Client review & handoff',done:false}]},
{id:'anorak',name:'The everyday outside',client:'Anorak',code:'ANO-003',team:'Art direction',owner:'Nadia Holt',initials:'NH',avatar:'three',status:'In progress',progress:34,due:'2026-11-18',art:'anorak',description:'A campaign finding the unexpected in familiar places. Art direction and a flexible content system for an outdoor brand with a different perspective.',tasks:[{name:'Campaign concept',done:true},{name:'Shoot direction',done:false},{name:'Campaign rollout',done:false},{name:'Final artwork',done:false}]},
{id:'fold',name:'Product language',client:'Fold',code:'FLD-004',team:'Digital design',owner:'Mia Torres',initials:'MT',avatar:'four',status:'Planned',progress:12,due:'2026-11-15',art:'fold',description:'A useful, human design language for the tools people work with every day. From core components to the details that make complex work feel simple.',tasks:[{name:'Product discovery',done:true},{name:'Component foundations',done:false},{name:'Critical user journeys',done:false},{name:'Developer handoff',done:false}]},
{id:'gather',name:'Launch toolkit',client:'Gather',code:'GTH-005',team:'Brand design',owner:'Sam Reed',initials:'SR',avatar:'two',status:'In review',progress:92,due:'2026-11-07',art:'gather',description:'The essentials for an introduction that lasts. A launch toolkit covering print, social and digital touchpoints for a neighborhood gathering place.',tasks:[{name:'Launch strategy',done:true},{name:'Print & social assets',done:true},{name:'Final refinements',done:true},{name:'Delivery package',done:false}]},
{id:'lune',name:'Editorial system',client:'Lune',code:'LUN-006',team:'Art direction',owner:'Iris Bell',initials:'IB',avatar:'three',status:'In progress',progress:46,due:'2026-11-21',art:'lune',description:'An editorial rhythm for a curious new voice. A flexible system for stories, images and the quieter moments in between.',tasks:[{name:'Editorial direction',done:true},{name:'Type & grid system',done:true},{name:'Issue templates',done:false},{name:'Final documentation',done:false}]}
];
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
let storageAvailable=true;
let projects=structuredClone(seed);
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(Array.isArray(saved)&&saved.length&&saved.every(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&typeof p.client==='string'&&Array.isArray(p.tasks)&&['In progress','In review','Planned','Completed'].includes(p.status))){projects=saved;}}catch(_){storageAvailable=false;}
let filterStatus='All',filterTeam='All',query='',layout='grid',sortBy='default',lastRoute='#overview',toastTimer;
const $=id=>document.getElementById(id);
function save(){try{localStorage.setItem(KEY,JSON.stringify(projects));}catch(_){storageAvailable=false;toast('Changes kept for this session. Browser storage is unavailable.');}}
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').classList.add('visible');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3600);}
function statusClass(status){return status==='In review'?'review':status==='Planned'?'planned':status==='Completed'?'completed':'';}
function status(p){return `<span class="status ${statusClass(p.status)}">${escapeHTML(p.status)}</span>`;}
function avatar(p){return `<span class="avatar ${p.avatar||''}" aria-label="${escapeHTML(p.owner)}">${escapeHTML(p.initials)}</span>`;}
function shortDate(value){return new Date(value+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});}
function art(p,detail=false){return `<div class="project-art art-${p.art||'fold'}${detail?' detail-art':''}" aria-hidden="true"><span class="art-word">${escapeHTML(p.client.toLowerCase())}</span>${p.art==='forma'?'<span class="art-label">EVERYDAY, CONSIDERED.</span>':p.art==='onda'?'<span class="art-label">A NEW WAVE OF SOUND.</span>':''}</div>`;}
function card(p){return `<article class="project-card"><button class="card-hit" data-open-project="${escapeHTML(p.id)}" aria-label="Open ${escapeHTML(p.client)}: ${escapeHTML(p.name)}">${art(p)}<div class="card-body"><div class="card-meta"><span class="project-code">${escapeHTML(p.code)}</span>${status(p)}</div><h3>${escapeHTML(p.client)} / ${escapeHTML(p.name)}</h3><p class="card-type">${escapeHTML(p.team)}</p><div class="progress-label"><span>Project progress</span><strong>${p.progress}%</strong></div><div class="progress-track"><span style="width:${p.progress}%"></span></div><div class="card-bottom"><span class="due">${icon('calendar')}${shortDate(p.due)}</span><div class="avatar-stack">${avatar(p)}<span class="avatar four" aria-label="Two more collaborators">+2</span></div></div></div></button></article>`;}
function renderOverview(){const active=projects.filter(p=>p.status!=='Completed');$('active-projects').textContent=String(active.length).padStart(2,'0');$('review-projects').textContent=String(projects.filter(p=>p.status==='In review').length).padStart(2,'0');$('featured-count').textContent=active.length;$('nav-count').textContent=projects.length;$('all-count').textContent=projects.length;$('featured-projects').innerHTML=active.slice(0,2).map(card).join('')||'<div class="empty"><h2>A clean slate.</h2><p>Your next project starts here.</p><button class="primary" data-create>New project</button></div>';}
function renderProjects(){let visible=projects.filter(p=>(filterStatus==='All'||p.status===filterStatus)&&(filterTeam==='All'||p.team===filterTeam)&&(!query||`${p.name} ${p.client} ${p.owner} ${p.code}`.toLowerCase().includes(query.toLowerCase())));if(sortBy==='due')visible.sort((a,b)=>a.due.localeCompare(b.due));if(sortBy==='name')visible.sort((a,b)=>a.client.localeCompare(b.client));$('results-label').textContent=`${visible.length} ${visible.length===1?'project':'projects'}${query?' matching "'+query+'"':''}${filterTeam!=='All'?' / '+filterTeam:''}`;const target=$('all-projects');target.className=layout==='grid'?'project-grid':'';if(!visible.length){target.innerHTML=`<div class="empty">${icon('projects')}<h2>${query?'No projects found.':filterStatus==='Completed'?'Good work takes a little time.':'A little space for new ideas.'}</h2><p>${query?'Try another name, client or project code.':filterStatus==='Completed'?'Completed projects will find a home here.':'There are no projects with these filters.'}</p><button class="secondary" id="clear-filters">Clear filters</button></div>`;return;}if(layout==='grid'){target.innerHTML=visible.map(card).join('');return;}target.innerHTML=`<table class="project-list"><thead><tr><th scope="col">Project</th><th scope="col">Status</th><th scope="col">Team</th><th scope="col">Delivery</th><th scope="col">Progress</th></tr></thead><tbody>${visible.map(p=>`<tr><td><button class="list-title" data-open-project="${escapeHTML(p.id)}"><span class="project-dot">${escapeHTML(p.client[0].toLowerCase())}</span><span>${escapeHTML(p.client)} / ${escapeHTML(p.name)}<small>${escapeHTML(p.owner)}</small></span></button></td><td>${status(p)}</td><td>${escapeHTML(p.team)}</td><td>${shortDate(p.due)}</td><td><div class="list-progress"><div class="progress-label"><span>${p.progress}%</span></div><div class="progress-track"><span style="width:${p.progress}%"></span></div></div></td></tr>`).join('')}</tbody></table>`;}
function setStatus(value){filterStatus=value;document.querySelectorAll('[data-status]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.status===value)));renderProjects();}
function resetFilters(){query='';$('global-search').value='';filterTeam='All';$('team-filter').value='All';setStatus('All');}
function openProject(id){const activity=$('activity-dialog');if(activity.open)activity.close();lastRoute=location.hash.startsWith('#project=')?lastRoute:(location.hash||'#overview');location.hash='project='+encodeURIComponent(id);}
function renderDetail(id){const p=projects.find(p=>p.id===id);if(!p){location.hash='projects';toast('That project is not in this workspace.');return;}const done=p.tasks.filter(t=>t.done).length;const action=p.status==='In progress'?'Move to review':p.status==='In review'?'Mark complete':p.status==='Planned'?'Start project':'Completed';$('detail-content').innerHTML=`${art(p,true)}<div class="detail-top"><div><span class="project-code">${escapeHTML(p.code)}</span><h2 id="detail-title">${escapeHTML(p.client)} / ${escapeHTML(p.name)}</h2><p>${escapeHTML(p.team)}</p></div>${status(p)}</div><div class="detail-layout"><div class="detail-content"><p class="detail-description">${escapeHTML(p.description)}</p><h3>Milestones <span style="float:right;font-weight:400;color:var(--muted);font-size:10px">${done} of ${p.tasks.length} complete</span></h3><div class="task-list">${p.tasks.map((t,i)=>`<label class="task-row"><input type="checkbox" data-task="${i}" data-project="${escapeHTML(p.id)}" ${t.done?'checked':''}><span>${escapeHTML(t.name)}</span><small>${t.done?'Done':'To do'}</small></label>`).join('')}</div><h3>Project progress</h3><div class="detail-progress"><div class="progress-label"><span>From first thought to final detail.</span><strong>${p.progress}%</strong></div><div class="progress-track"><span style="width:${p.progress}%"></span></div></div><p class="inline-state" id="milestone-feedback" aria-live="polite"></p></div><aside class="detail-aside"><dl><div><dt>Project lead</dt><dd>${avatar(p)}${escapeHTML(p.owner)}</dd></div><div><dt>Target delivery</dt><dd>${icon('calendar')}${shortDate(p.due)}, 2026</dd></div><div><dt>Team</dt><dd>${escapeHTML(p.team)}</dd></div><div><dt>Collaborators</dt><dd><div class="avatar-stack">${avatar(p)}<span class="avatar two">MT</span><span class="avatar three">NH</span></div></dd></div></dl><button class="primary" id="advance-project" data-project="${escapeHTML(p.id)}" ${p.status==='Completed'?'disabled':''} style="width:100%;font-size:10px;padding:9px 7px">${action}${p.status==='Completed'?'':icon('arrow')}</button></aside></div>`;const d=$('detail-dialog');if(!d.open)d.showModal();}
function renderCapacity(){const rows=[['Miki Chen','MC','Brand lead','','Forma','Forma','Forma','Gather','Gather','84%'],['Leo Park','LP','Digital lead','two','Onda','Onda','Onda','Onda','Open','92%'],['Nadia Holt','NH','Art director','three','Anorak','Anorak','Open','Anorak','Anorak','80%'],['Mia Torres','MT','Product designer','four','Fold','Fold','Onda','Open','Fold','78%'],['Sam Reed','SR','Brand designer','two','Gather','Gather','Gather','Gather','Open','86%'],['Iris Bell','IB','Designer','three','Lune','Lune','Open','Lune','Lune','76%'],['Jules Kim','JK','Designer','four','Forma','Forma','Open','Fold','Fold','80%'],['Owen Cole','OC','Producer','','Anorak','Onda','Gather','Open','Lune','80%']];$('capacity-resources').innerHTML='<div class="resource-row heading"><span>People / 8</span><span>MON 02</span><span>TUE 03</span><span style="color:var(--action)">WED 04</span><span>THU 05</span><span>FRI 06</span><span style="text-align:right">Utilized</span></div>'+rows.map(r=>`<div class="resource-row"><div class="resource-person"><span class="avatar ${r[3]}">${r[1]}</span><div><strong>${r[0]}</strong><small>${r[2]}</small></div></div>${r.slice(4,9).map(name=>name==='Open'?'<span class="resource-block empty">Available</span>':`<button class="resource-block ${['Onda','Fold'].includes(name)?'blue':''}" data-open-project="${name.toLowerCase()}" aria-label="Open ${name} project">${name}</button>`).join('')}<div class="resource-util"><strong>${r[9]}</strong></div></div>`).join('');}
function route(){const hash=location.hash||'#overview';if(hash.startsWith('#project=')){const anyVisible=document.querySelector('.view:not([hidden])');if(!anyVisible)$('view-overview').hidden=false;renderDetail(decodeURIComponent(hash.split('=')[1]));return;}const name=['#overview','#projects','#capacity'].includes(hash)?hash.slice(1):'overview';if($('detail-dialog').open)$('detail-dialog').close();lastRoute='#'+name;document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!=='view-'+name);document.querySelectorAll('[data-route]').forEach(a=>a.dataset.route===name?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current'));$('breadcrumb').textContent=name[0].toUpperCase()+name.slice(1);renderOverview();if(name==='projects')renderProjects();if(name==='capacity')renderCapacity();closeSidebar();document.title=`${name[0].toUpperCase()+name.slice(1)} - Pulse`;}
function createDialog(){const d=$('create-dialog');$('create-form').reset();$('project-due').value='2026-11-20';['name','client','due'].forEach(n=>$(n+'-error').textContent='');['project-name','client-name','project-due'].forEach(id=>$(id).removeAttribute('aria-invalid'));d.showModal();$('project-name').focus();}
function closeSidebar(){$('sidebar').classList.remove('open');$('sidebar-scrim').classList.add('hidden');$('menu-button').setAttribute('aria-expanded','false');}
document.addEventListener('click',e=>{const create=e.target.closest('[data-create]');if(create){createDialog();return;}const open=e.target.closest('[data-open-project]');if(open){openProject(open.dataset.openProject);return;}const close=e.target.closest('[data-close]');if(close){$(close.dataset.close).close();return;}if(e.target.closest('#clear-filters')){resetFilters();return;}const status=e.target.closest('[data-status]');if(status){setStatus(status.dataset.status);return;}const advance=e.target.closest('#advance-project');if(advance){const p=projects.find(p=>p.id===advance.dataset.project);if(!p)return;p.status=p.status==='Planned'?'In progress':p.status==='In progress'?'In review':'Completed';if(p.status==='Completed'){p.progress=100;p.tasks.forEach(t=>t.done=true);}save();renderOverview();renderProjects();renderDetail(p.id);toast(p.status==='Completed'?'Good work. Project complete.':p.client+' moved to '+p.status.toLowerCase()+'.');}});
document.addEventListener('change',e=>{if(e.target.matches('[data-task]')){const checkbox=e.target,p=projects.find(p=>p.id===checkbox.dataset.project);if(!p)return;p.tasks[Number(checkbox.dataset.task)].done=checkbox.checked;save();const index=checkbox.dataset.task;renderDetail(p.id);const replacement=$('detail-content').querySelector(`[data-task="${index}"]`);if(replacement)replacement.focus();$('milestone-feedback').textContent='Milestone updated.';}});
$('team-filter').addEventListener('change',e=>{filterTeam=e.target.value;renderProjects();});$('sort-filter').addEventListener('change',e=>{sortBy=e.target.value;renderProjects();});
function setLayout(value){layout=value;$('grid-button').setAttribute('aria-pressed',String(value==='grid'));$('list-button').setAttribute('aria-pressed',String(value==='list'));renderProjects();}
$('grid-button').addEventListener('click',()=>setLayout('grid'));$('list-button').addEventListener('click',()=>setLayout('list'));
$('global-search-form').addEventListener('submit',e=>{e.preventDefault();query=$('global-search').value.trim();location.hash='projects';renderProjects();});$('global-search').addEventListener('input',e=>{query=e.target.value.trim();if(location.hash==='#projects')renderProjects();});
$('notifications-button').addEventListener('click',()=>$('activity-dialog').showModal());$('menu-button').addEventListener('click',()=>{const open=$('sidebar').classList.toggle('open');$('sidebar-scrim').classList.toggle('hidden',!open);$('menu-button').setAttribute('aria-expanded',String(open));});$('sidebar-scrim').addEventListener('click',closeSidebar);
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('global-search').focus();}if(e.key==='Escape')closeSidebar();});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('detail-dialog').addEventListener('close',()=>{if(location.hash.startsWith('#project='))location.hash=lastRoute;});
$('create-form').addEventListener('submit',e=>{e.preventDefault();const name=$('project-name').value.trim(),client=$('client-name').value.trim(),due=$('project-due').value;let errors=[];const fields=[['project-name','name-error',name.length>=2?'':'Give the project a name with at least 2 characters.'],['client-name','client-error',client?'':'Add a client so the work has a home.'],['project-due','due-error',!due?'Choose a target delivery date.':due<'2026-11-04'?'Choose November 4 or a later date.':'']];fields.forEach(([id,error,message])=>{$(error).textContent=message;$(id).setAttribute('aria-invalid',String(!!message));if(message)errors.push(id);});if(errors.length){$(errors[0]).focus();return;}$('create-submit').disabled=true;const project={id:'project-'+Date.now().toString(36),name,client,code:'NEW-'+String(projects.length+1).padStart(3,'0'),team:$('project-team').value,owner:'Miki Chen',initials:'MC',avatar:'',status:'Planned',progress:0,due,art:'fold',description:$('project-notes').value.trim()||'A new project, ready for a clear direction and the right team.',tasks:[{name:'Set the creative direction',done:false},{name:'Explore & develop',done:false},{name:'Review together',done:false},{name:'Refine & deliver',done:false}]};projects.unshift(project);save();resetFilters();$('create-dialog').close();$('create-submit').disabled=false;location.hash='projects';renderOverview();renderProjects();toast('Project created. Good things ahead.');});
window.addEventListener('hashchange',route);renderOverview();renderProjects();renderCapacity();route();
